    [6] = {
      beijing = 1121,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "This wasn't the first time Lucien had been stopped by a passerby, but being recognized by someone was indeed a fresh experience for me.",
