    [7] = {
      beijing = 1121,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "Hearing us answer in the affirmative, the young man actually made a deep bow to us.",
      next = {8}
    },
    [8] = {
      beijing = 1121,
      dialog = 2,
      idx = 5,
      music = "30_WarmSnow",
      renming = "Young Man",
      renwu = "npc",
      ruchang = 0,
      sentence = "At first I thought, since the world was going to be destroyed soon, that it wouldn't matter if I go out looting in the streets, or something even more drastic.",
