    },
    [12] = {
      beijing = 1121,
      dialog = 2,
      idx = 5,
      music = "30_WarmSnow",
      renming = "Young Man",
      renwu = "npc",
      ruchang = 0,
      sentence = "Even if there is no way to change this outcome, I can at least choose what I do with the present.",
