      dialog = 2,
      idx = 5,
      music = "30_WarmSnow",
      renming = "Young Man",
      renwu = "npc",
      ruchang = 0,
      sentence = "So... thank you both.",
      next = {14}
    },
    [14] = {
      beijing = 1121,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      ruchang = 0,
      sentence = "The youth blurted all this out, almost to himself, then rushed off without waiting for a response.",
